files.tests/test_session_lifecycle.py:
from app.api import request_export

class Session:
    def __init__(self): self.closed = False
    def close(self): self.closed = True
    def fetch_name(self):
        if self.closed: raise RuntimeError('session closed')
        return 'Ada'

def test_background_task_does_not_capture_closed_session():
    session = Session()
    task = request_export(session)
    session.close()
    assert task() == 'Ada'

